  enunciado:"Qual das seguintes situações clínicas apresenta um quadro mais provável de doença reumatológica em um paciente com artralgia?",
  alternativas:[{id:"A",texto:"Paciente de 25 anos de idade, cefaleia recorrente, com resultado de Fator Antinuclear (FAN) 1:160, padrão citoplasmático fibrilar linear em exame de rotina."},{id:"B",texto:"Paciente de 60 anos de idade, com histórico de fadiga, com resultado de FAN 1:640, padrão nuclear pontilhado grosso."},{id:"C",texto:"Paciente de 30 anos de idade, em tratamento para acne com isotretinoína, com mialgias e resultado de FAN 1:320, padrão citoplasmático pontilhado polar."},{id:"D",texto:"Paciente de 45 anos de idade, com histórico de infecção respiratória recente, resultado de FAN 1:160, padrão citoplasmático fibrilar filamentar."}],
